        foreach ($ps as $i => $p) Package::updateOrCreate(['slug' => Str::slug($p[0])], ['title' => $p[0], 'destination' => $p[1], 'category' => $p[2], 'duration' => $p[3], 'price' => $p[4], 'old_price' => $p[4] + 5000, 'short_description' => 'A carefully planned ' . $p[1] . ' experience by TripNest.', 'description' => 'Enjoy a comfortable ' . $p[3] . ' journey with stays, sightseeing guidance and personal trip support. Contact TripNest for current dates and customisation.', 'featured_image' => $imgs[$i % 4], 'includes' => ['Accommodation', 'Trip assistance', 'Selected sightseeing', 'Breakfast'], 'excludes' => ['Personal expenses', 'Optional activities', 'Insurance'], 'featured' => $i < 7, 'active' => 1, 'sort_order' => $i]);
        foreach ([['Sunrise View', 'Island', 'Peaceful sunrise over the lagoon.', '🌅'], ['Sunset Cruise', 'Lagoon', 'Golden-hour boat ride.', '🌇'], ['Scuba Diving', 'Coral Reefs', 'Discover corals and marine life.', '🤿'], ['Fish Hunting', 'Lagoon', 'Traditional island fishing with local guidance.', '🎣'], ['Full Dweep View', 'View Point', 'See the lagoon and palms from above.', '🏝️'], ['Kalpitti Island View', 'Kalpitti', 'Scenic island viewpoint and beach time.', '🌴'], ['Glass Boat Ride', 'Coral Lagoon', 'See the underwater world from a glass-bottom boat.', '🚤']] as $i => $a) Activity::updateOrCreate(['title' => $a[0]], ['location' => $a[1], 'description' => $a[2], 'icon' => $a[3], 'image_path' => $imgs[$i % 4], 'price' => 1500 + $i * 500, 'duration' => '2–3 Hours', 'active' => 1, 'sort_order' => $i]);
        foreach ([['Bangaram Beach Resort', 'Bangaram, Lakshadweep', 4.8, 8999], ['Kavaratti Lagoon Resort', 'Kavaratti, Lakshadweep', 4.7, 6499], ['Agatti Coral Retreat', 'Agatti, Lakshadweep', 4.6, 5999], ['Kerala Backwater Retreat', 'Alleppey, Kerala', 4.7, 4999]] as $i => $r) Resort::updateOrCreate(['name' => $r[0]], ['location' => $r[1], 'description' => 'Comfortable stay selected by TripNest for a relaxed holiday.', 'rating' => $r[2], 'price_from' => $r[3], 'image_path' => $imgs[$i], 'amenities' => ['Wi-Fi', 'Breakfast', 'Beach access'], 'active' => 1, 'sort_order' => $i]);
        foreach ([['Lagoon Memories', 'Kochi', 'TripNest made our Lakshadweep trip smooth. Great resort and activities.', 5], ['Wonderful Family Trip', 'Bengaluru', 'The children loved the glass boat and sunset cruise.', 5], ['Perfect Honeymoon', 'Hyderabad', 'Beautiful stay, great planning and no stress.', 5], ['Student Adventure', 'Chennai', 'Affordable package and lots of fun activities.', 4]] as $i => $t) Testimonial::updateOrCreate(['customer_name' => $t[0]], ['location' => $t[1], 'message' => $t[2], 'rating' => $t[3], 'active' => 1, 'sort_order' => $i]);
        foreach ([['Lakshadweep Lagoon', 'Lakshadweep', $imgs[0]], ['Agatti Beach', 'Lakshadweep', $imgs[1]], ['Island Sunset', 'Lakshadweep', $imgs[2]], ['Kashmir Mountains', 'Kashmir', $imgs[3]], ['Kerala Backwaters', 'Kerala', $imgs[0]], ['Malaysia Escape', 'Malaysia', $imgs[1]]] as $i => $p) Photo::updateOrCreate(['title' => $p[0]], ['destination' => $p[1], 'caption' => 'TripNest destination moment.', 'image_path' => $p[2], 'active' => 1, 'sort_order' => $i]);
